    repo.WriteCompletedTask("alpha", "# Completed\n");

    // Needs-review task has a NEEDS-REVIEW marker under .relay/.
    repo.WriteTask("beta", "# Needs review\n");
    repo.WriteNeedsReview("beta", "Flagged: test failure");

